/bin/bash -lc "node --input-type=module <<'NODE'
import { spawn } from 'node:child_process';
import { once } from 'node:events';
import { readFileSync, rmSync } from 'node:fs';
import { Script } from 'node:vm';
const html = readFileSync('public/index.html', 'utf8');
new Script(html.match(/<script type=\"module\">([\\s\\S]*?)<\\/script>/)[1]);
const child = spawn('npm', ['start'], { env: { ...process.env, PORT: '18080', DB_PATH: './data/launch-check.sqlite' }, detached: true, stdio: ['ignore', 'pipe', 'pipe'] });
let output = '';
child.stdout.on('data', chunk => output += chunk);
child.stderr.on('data', chunk => output += chunk);
try {
  let healthy = false;
  for (let i = 0; i < 100; i++) {
    try {
      const response = await fetch('http://127.0.0.1:18080/health');
      if (response.status "'!== 200 || JSON.stringify(await response.json()) !== '"'{\"status\":\"ok\"}') throw new Error('Invalid health response');
      healthy = true;
      break;
    } catch { await new Promise(resolve => setTimeout(resolve, 30)); }
  }
  if ("'!healthy) throw new Error(output);
  console.log('"'npm start health check and browser JavaScript syntax check passed');
} finally {
  const exited = once(child, 'exit');
  process.kill(-child.pid, 'SIGTERM');
  await exited;
  for (const suffix of ['', '-shm', '-wal']) rmSync('./data/launch-check.sqlite' + suffix, { force: true });
}
NODE
 git diff --check && git add package.json server.js public/index.html test/projects.test.js README.md && git commit -m \"Implement persistent Workboard projects\" && git status --porcelain && git rev-parse HEAD"

